-- ─────────────────────────────────────────────
-- Auto-assign windows to workspaces
-- (equivalent to i3 assign + for_window workspace)
-- ─────────────────────────────────────────────

-- Obsidian → workspace 6
-- Generated by hyprlang2lua. Review TODOs before reloading Hyprland.

hl.window_rule({
    name = "obsidian",
    match = {
        class = "obsidian",
    },
    workspace = "6",
})

-- Discord + Telegram + Pachca → workspace 7
hl.window_rule({
    name = "TelegramDesktop",
    match = {
        class = "^(org\\.telegram\\.desktop)$",
    },
    workspace = "7",
    group = "set",
})

hl.window_rule({
    name = "Discord",
    match = {
        class = "discord",
    },
    workspace = "7",
    group = "set",
})

hl.window_rule({
    name = "pachca",
    match = {
        class = "Pachca",
    },
    workspace = "7",
    group = "set",
})

hl.window_rule({
    name = "Keet",
    match = {
        class = "Keet",
    },
    workspace = "7",
    group = "set",
})

-- Spotify → workspace 8
hl.window_rule({
    name = "Spotify",
    match = {
        class = "Spotify",
    },
    workspace = "8",
})

-- OBS Studio → workspace 10
hl.window_rule({
    name = "obs",
    match = {
        class = "com.obsproject.Studio",
    },
    workspace = "10",
})

-- AmneziaVPN → workspace 11
hl.window_rule({
    name = "amneziavpn",
    match = {
        class = "AmneziaVPN",
    },
    float = false,
    workspace = "11",
})

-- v2rayN → workspace 11
hl.window_rule({
    name = "v2rayN",
    match = {
        class = "v2rayN",
    },
    workspace = "11",
})

-- happ → workspace 11
hl.window_rule({
    name = "happ",
    match = {
        class = "happ",
    },
    workspace = "11",
})

-- throne → workspace 11
hl.window_rule({
    name = "throne",
    match = {
        class = "Throne",
    },
    workspace = "11",
})

