-- ─────────────────────────────────────────────
-- Try to emulate "layout tabbed" using groups
-- (best-effort – not perfect without hy3)
-- ─────────────────────────────────────────────

-- When these apps open → put them into a group automatically
-- (you can later use mod + G / mod + tab / etc to manage the group)

-- Example windowrule v1
-- windowrule = float, ^(kitty)$
-- Example windowrule v2
-- windowrulev2 = float,class:^(kitty)$,title:^(kitty)$
-- See https://wiki.hyprland.org/Configuring/Window-Rules/ for more
-- https://itsohen.github.io/hyprrulefix/ v2 -> v3
hl.window_rule({
    name = "windowrule-1",
    match = {
        class = ".*",
    },
    suppress_event = "maximize",
})

hl.window_rule({
    name = "windowrule-2",
    match = {
        title = "^(Picture(-|\\s)in(-|\\s)(p|P)icture)$",
    },
    float = true,
    pin = true,
})

hl.window_rule({
    name = "windowrule-3",
    match = {
        class = "org.pulseaudio.pavucontrol",
    },
    float = true,
    size = "(monitor_w*0.5) (monitor_h*0.5)",
})

hl.window_rule({
    name = "tilix",
    match = {
        class = "tilix",
    },
    opacity = "0.95 0.95",
})

