-- }

hl.window_rule({
    name = "windowrule-4",
    match = {
        class = "nemo",
    },
    float = true,
    size = "(monitor_w*0.5) (monitor_h*0.5)",
})

hl.window_rule({
    name = "satty",
    match = {
        class = "com.gabm.satty",
    },
    float = true,
    size = "(monitor_w*0.75) (monitor_h*0.75)",
})

hl.window_rule({
    name = "TelegramDesktopMediaViewer",
    match = {
        class = "org.telegram.desktop",
        title = "^Media viewer$",
    },
    fullscreen = false,
})

