hl.window_rule({
    name = "bitwarden",
    match = {
        class = "zen",
        title = "^(Bitwarden)$",
    },
    float = true,
})

hl.window_rule({
    name = "windowrule-9",
    match = {
        class = "^(com.github.hluk.copyq)$",
    },
    float = true,
})

-- Prevent tooltips from taking focus (always have a title of `win.<id>`)
hl.window_rule({
    name = "windowrule-10",
    match = {
        class = "^(.*jetbrains.*)$",
        title = "^(win.*)$",
    },
    no_initial_focus = true,
})

-- Make "Go to file" and other dialogs always focused when open
hl.window_rule({
    name = "windowrule-11",
    match = {
        class = "^(.*jetbrains.*)$",
        title = "^$",
        float = 1,
    },
    stay_focused = true,
})

-- fix tab dragging (always have a single space character as their title)
hl.window_rule({
    name = "windowrule-12",
    match = {
        class = "^(.*jetbrains.*)$",
        title = "^\\\\s$",
    },
    no_initial_focus = true,
})

-- Tile new tabs automatically
hl.window_rule({
    name = "windowrule-13",
    match = {
        class = "^(jetbrains-*)",
        float = 0,
    },
    float = false,
})

-- Fix splash screen showing in weird places and prevent annoying focus takeovers
hl.window_rule({
    name = "windowrule-14",
    match = {
        class = "^(jetbrains-.*)$",
        title = "^(splash)$",
        float = 1,
    },
    tag = "+jetbrains-splash",
})

hl.window_rule({
    name = "windowrule-15",
    match = {
        tag = "jetbrains-splash",
    },
    center = true,
    no_focus = true,
    border_size = 0,
})

-- Center popups/find windows
hl.window_rule({
    name = "windowrule-16",
    match = {
        class = "^(jetbrains-.*)",
        title = "^()$",
        float = 1,
    },
    tag = "+jetbrains",
    min_size = "(monitor_w*0.5) (monitor_h*0.5)",
})

hl.window_rule({
    name = "windowrule-17",
    match = {
        tag = "jetbrains",
    },
    center = true,
    stay_focused = true,
    border_size = 0,
})

-- Enabling this makes it possible to provide input in popup dialogs (search window, new file, etc.)

-- For some reason tag:jetbrains does not work for size rule

-- Disable window flicker when autocomplete or tooltips appear
hl.window_rule({
    name = "windowrule-18",
    match = {
        class = "^(jetbrains-.*)$",
        title = "^(win.*)$",
        float = 1,
    },
    no_initial_focus = true,
})

