--Float Steam windows by default, but tile main client if desired
-- TODO: manual review — top-level key '; windowrule = float, class:^()$,title:^(Steam - Self Updater)$' has no enclosing section

hl.window_rule({
    name = "windowrule-27",
    match = {
        class = "^(steam)$",
    },
    float = true,
})

-- Tile specific Steam sub-windows (e.g., Friends List) to avoid floating everything
hl.window_rule({
    name = "windowrule-28",
    match = {
        class = "^(steam)$",
        title = "Friends List",
    },
    float = false,
    size = "(monitor_w*0.3) (monitor_h*1)",
})

hl.window_rule({
    name = "windowrule-29",
    match = {
        class = "^(steam)$",
        title = "Steam",
    },
    float = false,
    size = "(monitor_w*0.7) (monitor_h*1)",
})

-- Fix disappearing dropdown menus in Steam (common XWayland issue)
hl.window_rule({
    name = "windowrule-30",
    match = {
        title = "^()$",
        class = "^(steam)$",
    },
    stay_focused = true,
    min_size = "1 1",
})

-- Minimum size for Friends List popup to prevent tiny windows
hl.window_rule({
    name = "windowrule-31",
    match = {
        class = "^(steam)$",
        title = "^(Friends.*)$",
    },
    min_size = "280 635",
})

-- Assign Steam to a specific workspace (e.g., workspace 9)
-- Split Steam and Friends List windows (e.g., 70% main, 30% friends)
-- Fullscreen all games (ignores borders for immersion)
hl.window_rule({
    name = "windowrule-32",
    match = {
        class = "^(gamescope)$",
    },
    fullscreen = true,
})

hl.window_rule({
    name = "windowrule-33",
    match = {
        class = "^(steam_app_.*)$",
    },
    fullscreen = true,
    opacity = "1.0 override",
})

-- Force opacity 1.0 for fullscreen games (prevents transparency issues)
hl.window_rule({
    name = "windowrule-34",
    match = {
        fullscreen = 1,
    },
    opacity = "1.0 override",
})

-- Example for a specific game (e.g., Path of Exile, appid 238960)
hl.window_rule({
    name = "windowrule-35",
    match = {
        class = "^(steam_app_238960)$",
    },
    fullscreen = true,
})

-- Mark windows as "game" content for better handling (e.g., immediate focus)
hl.window_rule({
    name = "windowrule-36",
    match = {
        content = "game",
    },
    immediate = true,
})

hl.window_rule({
    name = "windowrule-37",
    match = {
        initial_class = "^(steam_app_\\d+)$",
    },
    content = "game",
})


hl.window_rule({
    name = "hide_env_edit",
    no_screen_share = true,
    match = {
        class = "^(jetbrains-webstorm|com.mitchellh.ghostty)$",
        title = ".*\\.env.*"
    }
})
